1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --bg: #111418;
10	    --panel: #1b2027;
11	    --grid: #232a33;
12	    --text: #e8ecf1;
13	    --muted: #8b96a5;
14	    --I: #22c7e8;
15	    --O: #f2c613;
16	    --T: #a64ee0;
17	    --S: #3fc15a;
18	    --Z: #e8453c;
19	    --J: #3a6fe8;
20	    --L: #f08a24;
21	  }
22	  * { box-sizing: border-box; }
23	  body {
24	    margin: 0;
25	    min-height: 100vh;
26	    background: var(--bg);
27	    color: var(--text);
28	    font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
29	    display: flex;
30	    align-items: center;
31	    justify-content: center;
32	    padding: 16px;
33	  }
34	  .game { display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap; justify-content: center; }
35	  .board {
36	    display: grid;
37	    grid-template-columns: repeat(10, 28px);
38	    grid-template-rows: repeat(20, 28px);
39	    gap: 1px;
40	    background: var(--grid);
41	    border: 2px solid var(--grid);
42	    border-radius: 4px;
43	  }
44	  .cell { background: var(--bg); }
45	  .side { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
46	  .box { background: var(--panel); border-radius: 6px; padding: 10px 12px; }
47	  .label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
48	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
49	  .preview {
50	    display: grid;
51	    grid-template-columns: repeat(4, 20px);
52	    grid-template-rows: repeat(2, 20px);
53	    gap: 1px;
54	    margin-top: 6px;
55	  }
56	  .preview div { background: transparent; }
57	  .p-I { background: var(--I) !important; }
58	  .p-O { background: var(--O) !important; }
59	  .p-T { background: var(--T) !important; }
60	  .p-S { background: var(--S) !important; }
61	  .p-Z { background: var(--Z) !important; }
62	  .p-J { background: var(--J) !important; }
63	  .p-L { background: var(--L) !important; }
64	  button {
65	    background: var(--panel); color: var(--text); border: 1px solid var(--grid);
66	    border-radius: 6px; padding: 8px 12px; font: inherit; cursor: pointer;
67	  }
68	  button:hover { border-color: var(--muted); }
69	  .keys { color: var(--muted); font-size: 13px; }
70	</style>
71	</head>
72	<body>
73	<div class="game">
74	  <div class="board" data-testid="board" id="board"></div>
75	  <div class="side">
76	    <div class="box"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
77	    <div class="box"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
78	    <div class="box"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
79	    <div class="box"><div class="label">Next</div><div class="preview" id="preview"></div></div>
80	    <button id="restart" type="button">New game</button>
81	    <div class="keys">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop</div>
82	  </div>
83	</div>
84	<script>
85	(function () {
86	  "use strict";
87	
88	  var ROWS = 20, COLS = 10;
89	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
90	
91	  // Spawn shapes as [row, col] offsets from the piece origin.
92	  var SHAPES = {
93	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
94	    O: [[0, 1], [0, 2], [1, 1], [1, 2]],
95	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
96	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
97	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
98	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
99	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
100	  };
101	  // Side length of the square each shape rotates within.
102	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
103	  var SPAWN_COL = 3;
104	  var GRAVITY_MS = 1000;
105	
106	  // Locking rule (project decision): a gravity step that cannot move the piece
107	  // down counts one lock tick; the piece locks on the LOCK_TICKS-th tick.
108	  // Left/right while resting restarts the delay, at most MAX_LOCK_RESETS times
109	  // per piece. Hard drop locks at once.
110	  var LOCK_TICKS = 2;
111	  var MAX_LOCK_RESETS = 3;
112	  // Rotation tries these sideways shifts, in order, until one fits.
113	  var KICKS = [0, -1, 1, -2, 2];
114	
115	  var state = {
116	    board: [],      // ROWS x COLS, "" or piece letter
117	    current: null,  // { type, row, col, shape, lockTicks, lockResets }
118	    next: [],
119	    score: 0,
120	    level: 1,
121	    lines: 0,
122	    status: "running"
123	  };
124	
125	  // ---- core logic ----
126	
127	  function emptyBoard() {
128	    var b = [];
129	    for (var r = 0; r < ROWS; r++) {
130	      var row = [];
131	      for (var c = 0; c < COLS; c++) row.push("");
132	      b.push(row);
133	    }
134	    return b;
135	  }
136	
137	  function randomType() {
138	    return TYPES[Math.floor(Math.random() * TYPES.length)];
139	  }
140	
141	  function cellsOf(piece, dRow, dCol) {
142	    return piece.shape.map(function (o) {
143	      return [piece.row + (dRow || 0) + o[0], piece.col + (dCol || 0) + o[1]];
144	    });
145	  }
146	
147	  function fits(piece, dRow, dCol) {
148	    return cellsOf(piece, dRow, dCol).every(function (p) {
149	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && state.board[p[0]][p[1]] === "";
150	    });
151	  }
152	
153	  function spawn() {
154	    var type = state.next.length ? state.next.shift() : randomType();
155	    if (!state.next.length) state.next.push(randomType());
156	    state.current = { type: type, row: 0, col: SPAWN_COL, shape: SHAPES[type], lockTicks: 0, lockResets: 0 };
157	  }
158	
159	  function lock() {
160	    var piece = state.current;
161	    cellsOf(piece).forEach(function (p) { state.board[p[0]][p[1]] = piece.type; });
162	    state.current = null;
163	    spawn();
164	  }
165	
166	  function tryMove(dRow, dCol) {
167	    if (!state.current || !fits(state.current, dRow, dCol)) return false;
168	    state.current.row += dRow;
169	    state.current.col += dCol;
170	    if (dRow > 0) state.current.lockTicks = 0;
171	    return true;
172	  }
173	
174	  // Sideways move. If the lock delay is running, restart it (capped per piece).
175	  function shift(dCol) {
176	    var piece = state.current;
177	    if (!tryMove(0, dCol)) return;
178	    if (piece.lockTicks > 0 && piece.lockResets < MAX_LOCK_RESETS) {
179	      piece.lockResets++;
180	      piece.lockTicks = 0;
181	    }
182	  }
183	
184	  function rotateCW() {
185	    var piece = state.current;
186	    if (!piece || piece.type === "O") return;
187	    var n = BOX[piece.type];
188	    var turned = {
189	      type: piece.type, row: piece.row, col: piece.col,
190	      shape: piece.shape.map(function (o) { return [o[1], n - 1 - o[0]]; })
191	    };
192	    for (var i = 0; i < KICKS.length; i++) {
193	      if (fits(turned, 0, KICKS[i])) {
194	        piece.shape = turned.shape;
195	        piece.col += KICKS[i];
196	        return;
197	      }
198	    }
199	  }
200	
201	  // One gravity step. The timer and __tetris.tick both call this.
202	  function gravityStep() {
203	    if (state.status !== "running" || !state.current) return;
204	    if (tryMove(1, 0)) return;
205	    state.current.lockTicks++;
206	    if (state.current.lockTicks >= LOCK_TICKS) lock();
207	  }
208	
209	  var actions = {
210	    left: function () { if (state.current) shift(-1); },
211	    right: function () { if (state.current) shift(1); },
212	    rotateCW: rotateCW,
213	    softDrop: function () { tryMove(1, 0); },
214	    hardDrop: function () {
215	      if (!state.current) return;
216	      while (tryMove(1, 0)) {}
217	      lock();
218	    }
219	  };
220	
221	  function doAction(name) {
222	    if (state.status !== "running" || !actions[name]) return;
223	    actions[name]();
224	    render();
225	  }
226	
227	  function newGame(queue) {
228	    state.board = emptyBoard();
229	    state.score = 0;
230	    state.level = 1;
231	    state.lines = 0;
232	    state.status = "running";
233	    state.next = Array.isArray(queue) ? queue.slice() : [];
234	    spawn();
235	    restartTimer();
236	    render();
237	  }
238	
239	  // ---- rendering (synchronous) ----
240	
241	  var boardEl = document.getElementById("board");
242	  var previewEl = document.getElementById("preview");
243	  var scoreEl = document.getElementById("score");
244	  var levelEl = document.getElementById("level");
245	  var linesEl = document.getElementById("lines");
246	  var cellEls = [];
247	  var previewEls = [];
248	
249	  (function buildDom() {
250	    for (var r = 0; r < ROWS; r++) {
251	      var row = [];
252	      for (var c = 0; c < COLS; c++) {
253	        var el = document.createElement("div");
254	        el.className = "cell";
255	        el.setAttribute("data-testid", "cell");
256	        el.setAttribute("data-row", String(r));
257	        el.setAttribute("data-col", String(c));
258	        el.setAttribute("data-filled", "false");
259	        el.setAttribute("data-piece", "");
260	        boardEl.appendChild(el);
261	        row.push(el);
262	      }
263	      cellEls.push(row);
264	    }
265	    for (var i = 0; i < 8; i++) {
266	      var p = document.createElement("div");
267	      previewEl.appendChild(p);
268	      previewEls.push(p);
269	    }
270	  })();
271	
272	  function paint(el, type) {
273	    el.className = el.className.replace(/\s*p-[A-Z]/g, "") + (type ? " p-" + type : "");
274	  }
275	
276	  function render() {
277	    var view = state.board.map(function (row) { return row.slice(); });
278	    if (state.current) {
279	      cellsOf(state.current).forEach(function (p) {
280	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) view[p[0]][p[1]] = state.current.type;
281	      });
282	    }
283	    for (var r = 0; r < ROWS; r++) {
284	      for (var c = 0; c < COLS; c++) {
285	        var el = cellEls[r][c], t = view[r][c];
286	        el.setAttribute("data-filled", t ? "true" : "false");
287	        el.setAttribute("data-piece", t);
288	        paint(el, t);
289	      }
290	    }
291	    previewEls.forEach(function (el) { paint(el, ""); });
292	    var nextType = state.next[0];
293	    if (nextType) {
294	      SHAPES[nextType].forEach(function (o) { paint(previewEls[o[0] * 4 + o[1]], nextType); });
295	    }
296	    scoreEl.textContent = String(state.score);
297	    levelEl.textContent = String(state.level);
298	    linesEl.textContent = String(state.lines);
299	  }
300	
301	  // ---- timer ----
302	
303	  var timer = null;
304	  function onTimer() { gravityStep(); render(); }
305	  function restartTimer() {
306	    if (timer) clearInterval(timer);
307	    timer = setInterval(onTimer, GRAVITY_MS);
308	  }
309	
310	  // ---- input ----
311	
312	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };
313	  document.addEventListener("keydown", function (e) {
314	    var action = KEYS[e.key];
315	    if (!action) return;
316	    e.preventDefault();
317	    doAction(action);
318	  });
319	  document.getElementById("restart").addEventListener("click", function (e) {
320	    e.currentTarget.blur();
321	    newGame();
322	  });
323	
324	  // ---- test control surface ----
325	
326	  window.__tetris = {
327	    newGame: function (queue) { newGame(queue); },
328	    setQueue: function (queue) {
329	      state.next = Array.isArray(queue) ? queue.slice() : [];
330	      render();
331	    },
332	    setBoard: function (rows) {
333	      state.board = rows.map(function (line) {
334	        return line.split("").map(function (ch) { return ch === "." ? "" : ch; });
335	      });
336	      render();
337	    },
338	    tick: function (n) {
339	      var steps = n === undefined ? 1 : n;
340	      for (var i = 0; i < steps; i++) gravityStep();
341	      render();
342	    },
343	    input: function (action) { doAction(action); },
344	    getBoard: function () {
345	      return state.board.map(function (row) {
346	        return row.map(function (t) { return t || "."; }).join("");
347	      });
348	    },
349	    getState: function () {
350	      return {
351	        current: state.current
352	          ? { type: state.current.type, cells: cellsOf(state.current) }
353	          : null,
354	        next: state.next.slice(),
355	        score: state.score,
356	        level: state.level,
357	        lines: state.lines,
358	        status: state.status
359	      };
360	    }
361	  };
362	
363	  newGame();
364	})();
365	</script>
366	</body>
367	</html>
